-- ============================================================
-- Migration: 20261104000008 — Import MHO companions (buddies)
-- Source: import/MHO_companions.csv + import/MHO_companions.json (+ import/Companions)
--   * buddies.id becomes the numeric id from the CSV; the 'lucky' buddy (not in the file) is kept
--   * existing core_passive, notes, name_ja and is_active are carried over
--   * new columns: species, description, default_of_adventurer_id
--   * new table buddy_skills (skills, passive skills and unique skills, with descriptions)
--   * image = companion bust (256px WebP) in /images/buddies/
--   * user collections, challenges and builds are re-pointed from the old text ids
-- ============================================================

BEGIN;

ALTER TABLE public.buddies
  ADD COLUMN IF NOT EXISTS species                  TEXT,
  ADD COLUMN IF NOT EXISTS description              TEXT,
  ADD COLUMN IF NOT EXISTS default_of_adventurer_id TEXT
    REFERENCES public.adventurers(id) ON UPDATE CASCADE ON DELETE SET NULL;

CREATE TABLE IF NOT EXISTS public.buddy_skills (
  id          UUID        PRIMARY KEY DEFAULT gen_random_uuid(),
  buddy_id    TEXT        NOT NULL REFERENCES public.buddies(id) ON DELETE CASCADE ON UPDATE CASCADE,
  kind        TEXT        NOT NULL CHECK (kind IN ('skill', 'passive', 'other')),
  sort_order  INTEGER     NOT NULL DEFAULT 0,
  name        TEXT        NOT NULL,
  description TEXT
);
CREATE INDEX IF NOT EXISTS idx_buddy_skills_buddy ON public.buddy_skills(buddy_id, kind, sort_order);

ALTER TABLE public.buddy_skills ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "buddy_skills_select_all" ON public.buddy_skills;
CREATE POLICY "buddy_skills_select_all" ON public.buddy_skills FOR SELECT USING (TRUE);
DROP POLICY IF EXISTS "buddy_skills_admin_all" ON public.buddy_skills;
CREATE POLICY "buddy_skills_admin_all" ON public.buddy_skills FOR ALL
  USING (EXISTS (SELECT 1 FROM public.profiles WHERE id = auth.uid() AND role = 'admin'));

CREATE TEMP TABLE _buddy_import (
  id TEXT PRIMARY KEY, old_id TEXT, name TEXT NOT NULL, species TEXT, tier TEXT, role TEXT,
  description TEXT, default_of TEXT, image TEXT, sort_order INTEGER
) ON COMMIT DROP;
