INSERT INTO public.buddies
  (id, name, name_ja, tier, role, core_passive, image, is_active, notes, sort_order,
   species, description, default_of_adventurer_id)
SELECT i.id, i.name, o.name_ja, i.tier, i.role, o.core_passive, i.image, COALESCE(o.is_active, TRUE), o.notes, i.sort_order,
       i.species, i.description,
       (SELECT a.id FROM public.adventurers a WHERE a.name = i.default_of LIMIT 1)
FROM _buddy_import i
LEFT JOIN public.buddies o ON o.id = i.old_id;

UPDATE public.user_buddy_collection t SET buddy_id = i.id FROM _buddy_import i WHERE t.buddy_id = i.old_id;
UPDATE public.hunter_challenges t SET buddy_id = i.id FROM _buddy_import i WHERE t.buddy_id = i.old_id;
UPDATE public.mho_builds t SET buddy_id = i.id FROM _buddy_import i WHERE t.buddy_id = i.old_id;

-- Challenges keep a copy of the portrait; point it at the new image
UPDATE public.hunter_challenges h SET piece_image = b.image, set_icon = b.image
FROM public.buddies b WHERE h.buddy_id = b.id AND h.buddy_id IN (SELECT id FROM _buddy_import);

DELETE FROM public.buddies WHERE id IN (SELECT old_id FROM _buddy_import WHERE old_id IS NOT NULL);

-- Buddies not in the file (Lucky) go after the imported ones
UPDATE public.buddies SET sort_order = 999 WHERE id NOT IN (SELECT id FROM _buddy_import);

